@startuml
class User {
  +id : long
  +name : string
  +email : string
  +dateOfBirth : date
}

class Account {
  +accountNumber : long
}

class BusinessAccount extends Account {
  +companyName : string
  +monthlyFee : float
}

class PersonalAccount extends Account {
}

class Page {
  +pageName : string
  +numberOfVisits : int
}

class AdvertisementPage extends Page {
  +bounceRate : float
  +clickThroughRate : float
  +conversionRate : float
}

User "1" -- "0..1" Account : has
Account "1" -- "0..*" Page : administrates
PersonalAccount "0..1" -- "0..*" Page : granted privileges
BusinessAccount "1" -- "0..*" AdvertisementPage : creates
@enduml

